class Solution {
public:
    int minSwap(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        int swp = 1, noswp = 0;
        for (int i = 1; i < n; i++) {
            int a1 = nums1[i-1], b1 = nums2[i-1];
            int a2 = nums1[i],   b2 = nums2[i];
            int new_swp = n, new_noswp = n;
            if (a1 < a2 && b1 < b2) {
                new_noswp = min(new_noswp, noswp);
                new_swp   = min(new_swp,   swp + 1);
            }
            if (b1 < a2 && a1 < b2) {
                new_noswp = min(new_noswp, swp);
                new_swp   = min(new_swp,   noswp + 1);
            }
            swp = new_swp;
            noswp = new_noswp;
        }
        return min(swp, noswp);
    }
};
